(() => {
  "use strict";

  const $ = (s, el = document) => el.querySelector(s);
  const $$ = (s, el = document) => [...el.querySelectorAll(s)];
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const reduceMotion = matchMedia("(prefers-reduced-motion: reduce)").matches;

  /* ---------------------------------------------------------------
   * 1. Photos: manifest (generated by serve.py from real files) →
   *    common name/extension fallbacks → sunflower placeholder.
   * ------------------------------------------------------------- */
  const MANIFEST = window.PHOTO_MANIFEST || {};
  const EXTS = ["jpg", "jpeg", "png", "webp", "JPG", "JPEG", "PNG", "WEBP"];
  const MIN_SIZE = 24; // smaller than this = blank/broken file

  // With serve.py's manifest the file list is authoritative: a missing slot goes straight to the
  // placeholder instead of probing guesses (each failed guess would log a 404 in the console).
  const MANIFEST_OK = window.MEDIA_MANIFEST_OK === true;
  function candidates(n) {
    const list = [];
    if (MANIFEST[n]) list.push(MANIFEST[n]);
    if (MANIFEST_OK) return list;
    for (const dir of ["photos", "Photos"]) for (const ext of EXTS) list.push(`${dir}/photo${n}.${ext}`);
    return [...new Set(list)];
  }

  const photoCache = new Map();
  function resolvePhoto(n) {
    if (photoCache.has(n)) return photoCache.get(n);
    const p = new Promise((resolve) => {
      const list = candidates(n);
      let i = 0;
      const tryNext = () => {
        if (i >= list.length) return resolve(null);
        const url = list[i++];
        const probe = new Image();
        probe.onload = () => {
          if (probe.naturalWidth < MIN_SIZE || probe.naturalHeight < MIN_SIZE) {
            console.warn(`[photos] photo${n} (${url}) is only ${probe.naturalWidth}x${probe.naturalHeight}px - showing placeholder`);
            return resolve(null);
          }
          resolve(url);
        };
        probe.onerror = tryNext;
        probe.src = url;
      };
      tryNext();
    });
    photoCache.set(n, p);
    return p;
  }

  $$("img[data-photo]").forEach((img) => {
    const n = img.dataset.photo;
    const holder = img.closest(".ph");
    holder.dataset.label = `photo ${n}`;
    resolvePhoto(n).then((url) => {
      if (!url) { holder.classList.add("missing"); return; }
      img.addEventListener("load", () => img.classList.add("loaded"), { once: true });
      img.addEventListener("error", () => holder.classList.add("missing"), { once: true });
      img.decoding = "async";
      img.src = url;
    });
  });

  /* ---------------------------------------------------------------
   * 2. 3D page stage + navigation, with Page 2 locked until YES
   * ------------------------------------------------------------- */
  const viewport = $("#viewport");
  const stage = $("#stage");
  const pages = $$(".page", stage);
  const dotsNav = $("#dotsNav");
  const prevBtn = $("#prevBtn");
  const nextBtn = $("#nextBtn");
  const yesBtn = $("#yesBtn");
  const noBtn = $("#noBtn");
  const gatePage = yesBtn.closest(".page");
  const gateCard = $("#gateCard");
  const gateHint = $("#gateHint");
  const GATE_INDEX = pages.indexOf(gatePage);
  const DURATION = reduceMotion ? 50 : 1050;

  let index = 0;
  let lastNav = -Infinity;
  let gateOpen = false;

  pages.forEach((pg, i) => {
    const b = document.createElement("button");
    b.type = "button";
    b.title = pg.dataset.title || `Page ${i + 1}`;
    b.setAttribute("aria-label", `Go to page ${i + 1}: ${b.title}`);
    b.addEventListener("click", () => go(i));
    dotsNav.appendChild(b);
  });
  const dots = $$("button", dotsNav);

  // Height comes from CSS (100dvh); only fall back to JS where dvh is unsupported.
  const setVH = () => {
    if (!CSS.supports("height", "100dvh")) document.documentElement.style.setProperty("--vh", `${window.innerHeight}px`);
  };

  function render() {
    pages.forEach((pg, i) => {
      pg.classList.toggle("active", i === index);
      pg.classList.toggle("is-before", i < index);
      pg.classList.toggle("is-after", i > index);
      pg.setAttribute("aria-hidden", i === index ? "false" : "true");
      pg.inert = i !== index;
    });
    dots.forEach((d, i) => {
      d.setAttribute("aria-current", i === index ? "true" : "false");
      const locked = !gateOpen && i > GATE_INDEX;
      d.classList.toggle("locked", locked);
      d.title = locked ? "Locked - say YES first!" : pages[i].dataset.title;
    });
    prevBtn.disabled = index === 0;
    nextBtn.disabled = index === pages.length - 1;
    nextBtn.classList.toggle("locked", !gateOpen && index === GATE_INDEX);
    history.replaceState(null, "", `#${index + 1}`);
    pages.forEach((pg, i) => { if (i !== index || pg.classList.contains("media-page")) resetTilt(pg.querySelector(".card")); });
    document.body.classList.toggle("on-media", pages[index].classList.contains("media-page"));
    syncMedia();
  }

  let hintTimer = 0;
  function blockedFeedback() {
    if (index !== GATE_INDEX) return;
    gateHint.classList.add("show");
    clearTimeout(hintTimer);
    hintTimer = setTimeout(() => gateHint.classList.remove("show"), 2600);
    for (const el of [yesBtn, gateCard]) {
      const cls = el === yesBtn ? "shake" : "bump";
      el.classList.remove(cls);
      void el.offsetWidth;
      el.classList.add(cls);
    }
  }
  yesBtn.addEventListener("animationend", () => yesBtn.classList.remove("shake"));
  gateCard.addEventListener("animationend", (e) => { if (e.target === gateCard) gateCard.classList.remove("bump"); });

  /** The single gatekeeper: every navigation path goes through here. */
  function go(i) {
    i = clamp(i, 0, pages.length - 1);
    if (!gateOpen && i > GATE_INDEX) {
      if (index === GATE_INDEX) { blockedFeedback(); return false; }
      i = GATE_INDEX; // e.g. jumping from page 1 to a locked page lands on the gate
    }
    if (i === index) return false;
    index = i;
    lastNav = performance.now();
    render();
    return true;
  }
  const next = () => go(index + 1);
  const prev = () => go(index - 1);
  const busy = () => performance.now() - lastNav < DURATION;

  prevBtn.addEventListener("click", prev);
  nextBtn.addEventListener("click", next);

  // Buttons with data-go="<pageIndex>" slide there. YES is the only thing that unlocks the gate.
  $$("[data-go]").forEach((el) =>
    el.addEventListener("click", (e) => {
      if (el === yesBtn) {
        gateOpen = true;
        gateHint.classList.remove("show");
      }
      if (el.hasAttribute("data-confetti")) confetti(e.clientX, e.clientY);
      go(Number(el.dataset.go));
    })
  );

  // Wheel / trackpad: one page per gesture; inertia can't double-skip.
  let wheelAcc = 0, lastWheel = 0, wheelLocked = false;
  const WHEEL_GAP = 220, WHEEL_THRESHOLD = 45;
  window.addEventListener("wheel", (e) => {
    e.preventDefault();
    const now = performance.now();
    const gap = now - lastWheel;
    lastWheel = now;
    if (wheelLocked) {
      if (!busy() && gap > WHEEL_GAP) wheelLocked = false;
      else return;
    }
    if (gap > WHEEL_GAP) wheelAcc = 0;
    const unit = e.deltaMode === 1 ? 16 : e.deltaMode === 2 ? window.innerHeight : 1;
    wheelAcc += (Math.abs(e.deltaY) >= Math.abs(e.deltaX) ? e.deltaY : e.deltaX) * unit;
    if (Math.abs(wheelAcc) >= WHEEL_THRESHOLD) {
      const moved = wheelAcc > 0 ? next() : prev();
      wheelAcc = 0;
      wheelLocked = true; // also swallow the rest of a blocked gesture
      if (!moved) lastNav = now - DURATION + 350;
    }
  }, { passive: false });

  // Keyboard
  window.addEventListener("keydown", (e) => {
    const k = e.key;
    const fwd = ["ArrowDown", "PageDown", " ", "ArrowRight"].includes(k);
    const back = ["ArrowUp", "PageUp", "ArrowLeft"].includes(k);
    if (k === " " && e.target.closest && e.target.closest("button")) return; // space activates buttons
    if (fwd) { e.preventDefault(); if (!busy()) next(); }
    else if (back) { e.preventDefault(); if (!busy()) prev(); }
    else if (k === "Home") { e.preventDefault(); go(0); }
    else if (k === "End") { e.preventDefault(); go(pages.length - 1); }
  });

  // Touch swipe
  let touchY = null, touchX = null, touchOnNo = false;
  window.addEventListener("touchstart", (e) => {
    touchY = e.touches[0].clientY; touchX = e.touches[0].clientX;
    touchOnNo = !!e.target.closest("#noBtn");
  }, { passive: true });
  window.addEventListener("touchmove", (e) => { if (e.cancelable) e.preventDefault(); }, { passive: false });
  window.addEventListener("touchend", (e) => {
    if (touchY == null || touchOnNo) { touchY = null; return; }
    const dy = touchY - e.changedTouches[0].clientY;
    const dx = touchX - e.changedTouches[0].clientX;
    touchY = null;
    if (Math.abs(dy) > 50 && Math.abs(dy) > Math.abs(dx) && !busy()) dy > 0 ? next() : prev();
  }, { passive: true });

  // Never let the browser natively scroll the stage (find-in-page, focus, scrollIntoView…)
  for (const el of [viewport, stage, document.scrollingElement]) {
    el.addEventListener("scroll", () => { el.scrollTop = 0; el.scrollLeft = 0; });
  }

  // Resize: snap without animating
  let resizeRaf = 0;
  window.addEventListener("resize", () => {
    cancelAnimationFrame(resizeRaf);
    resizeRaf = requestAnimationFrame(() => {
      stage.classList.add("no-anim");
      setVH();
      render();
      keepNoInBounds();
      fitMediaText();
      void stage.offsetHeight;
      stage.classList.remove("no-anim");
    });
  });

  /* ---------------------------------------------------------------
   * 3. The runaway "NO" button - stays inside Page 2's card
   * ------------------------------------------------------------- */
  const DODGE_RADIUS = 70;
  const SAFE_DIST = 160;
  const MARGIN = 14;
  // NO must never land on text, YES, or the corner decorations.
  const AVOID_TEXT = $$(".title, .passage, .gate-hint, .cluster, .torn-corner, .deco", gatePage);
  let lastDodge = 0;

  function freeNo() {
    if (noBtn.classList.contains("free")) return;
    const cr = gateCard.getBoundingClientRect();
    const br = noBtn.getBoundingClientRect();
    noBtn.style.transition = "none";
    gateCard.appendChild(noBtn);
    noBtn.classList.add("free");
    noBtn.style.left = `${br.left - cr.left}px`;
    noBtn.style.top = `${br.top - cr.top}px`;
    void noBtn.offsetWidth;
    noBtn.style.transition = "";
  }

  const overlaps = (a, b, pad = 0) =>
    a.left < b.right + pad && a.right > b.left - pad && a.top < b.bottom + pad && a.bottom > b.top - pad;

  function dodge(px, py) {
    const now = performance.now();
    if (now - lastDodge < 110) return;
    lastDodge = now;
    freeNo();
    const cr = gateCard.getBoundingClientRect();
    const w = noBtn.offsetWidth, h = noBtn.offsetHeight;
    // Never cover YES (generous gap) or the page's text.
    const avoid = [[yesBtn.getBoundingClientRect(), 24], ...AVOID_TEXT.map((el) => [el.getBoundingClientRect(), 8])];
    const maxX = Math.max(MARGIN, cr.width - w - MARGIN);
    const maxY = Math.max(MARGIN, cr.height - h - MARGIN);
    let best = null, bestScore = -1;
    for (let t = 0; t < 80; t++) {
      const x = MARGIN + Math.random() * (maxX - MARGIN);
      const y = MARGIN + Math.random() * (maxY - MARGIN);
      const r = { left: cr.left + x, top: cr.top + y, right: cr.left + x + w, bottom: cr.top + y + h };
      if (avoid.some(([a, pad]) => overlaps(r, a, pad))) continue;
      const d = Math.hypot(r.left + w / 2 - px, r.top + h / 2 - py);
      if (d >= SAFE_DIST) { best = { x, y }; break; }
      if (d > bestScore) { bestScore = d; best = { x, y }; }
    }
    if (best) {
      noBtn.style.left = `${best.x}px`;
      noBtn.style.top = `${best.y}px`;
    }
  }

  // After a resize, pick a fresh valid spot (inside the card, clear of YES and text).
  function keepNoInBounds() {
    if (!noBtn.classList.contains("free")) return;
    const cr = gateCard.getBoundingClientRect();
    lastDodge = 0;
    dodge(cr.left - 9999, cr.top - 9999); // "pointer" far away: any valid spot is fine
  }

  function distToRect(px, py, r) {
    const dx = Math.max(r.left - px, 0, px - r.right);
    const dy = Math.max(r.top - py, 0, py - r.bottom);
    return Math.hypot(dx, dy);
  }

  window.addEventListener("pointermove", (e) => {
    if (index !== GATE_INDEX || e.pointerType === "touch") return;
    if (distToRect(e.clientX, e.clientY, noBtn.getBoundingClientRect()) < DODGE_RADIUS) dodge(e.clientX, e.clientY);
  });
  const dodgeFromSelf = () => {
    const r = noBtn.getBoundingClientRect();
    lastDodge = 0;
    dodge(r.left + r.width / 2, r.top + r.height / 2);
  };
  noBtn.addEventListener("pointerenter", (e) => dodge(e.clientX, e.clientY));
  noBtn.addEventListener("pointerdown", (e) => { e.preventDefault(); dodge(e.clientX, e.clientY); });
  noBtn.addEventListener("click", (e) => { e.preventDefault(); dodgeFromSelf(); });
  noBtn.addEventListener("focus", dodgeFromSelf);

  /* ---------------------------------------------------------------
   * 4. Cursor-driven 3D: card tilt + golden sheen + page glow +
   *    parallax (sunflowers drift with the cursor, frames against it)
   * ------------------------------------------------------------- */
  const TILT_X = 7;   // max rotateX (deg)
  const TILT_Y = 9;   // max rotateY (deg)
  const rootStyle = document.documentElement.style;
  const glow = document.createElement("div");
  glow.className = "cursor-glow";
  glow.setAttribute("aria-hidden", "true");
  document.body.appendChild(glow);

  function resetTilt(card) {
    if (!card) return;
    for (const p of ["--tilt-x", "--tilt-y", "--tilt-s", "--tnx", "--tny", "--sheen"]) card.style.removeProperty(p);
  }

  if (!reduceMotion) {
    let raf = 0, last = null;
    const apply = () => {
      raf = 0;
      if (!last) return;
      const { x, y } = last;
      rootStyle.setProperty("--px", ((x / innerWidth) * 2 - 1).toFixed(3));
      rootStyle.setProperty("--py", ((y / innerHeight) * 2 - 1).toFixed(3));
      glow.style.transform = `translate3d(${x}px, ${y}px, 0)`;
      glow.classList.add("on");

      // Cursor tilt / sheen only on pages 1-2; media pages (3-5) stay flat.
      if (pages[index].classList.contains("media-page")) return;
      const card = pages[index].querySelector(".card");
      const r = card.getBoundingClientRect();
      const nx = clamp((x - (r.left + r.width / 2)) / (r.width / 2), -1, 1);
      const ny = clamp((y - (r.top + r.height / 2)) / (r.height / 2), -1, 1);
      const inside = x >= r.left && x <= r.right && y >= r.top && y <= r.bottom;
      card.style.setProperty("--tilt-x", `${(-ny * TILT_X).toFixed(2)}deg`);
      card.style.setProperty("--tilt-y", `${(nx * TILT_Y).toFixed(2)}deg`);
      card.style.setProperty("--tilt-s", (1 - 0.0105 * Math.max(Math.abs(nx * TILT_Y), Math.abs(ny * TILT_X))).toFixed(4));
      card.style.setProperty("--tnx", (-ny * TILT_X).toFixed(2));
      card.style.setProperty("--tny", (nx * TILT_Y).toFixed(2));
      card.style.setProperty("--sx", `${(((x - r.left) / r.width) * 100).toFixed(1)}%`);
      card.style.setProperty("--sy", `${(((y - r.top) / r.height) * 100).toFixed(1)}%`);
      card.style.setProperty("--sheen", inside ? "1" : "0");
    };
    window.addEventListener("pointermove", (e) => {
      if (e.pointerType === "touch") return;
      last = { x: e.clientX, y: e.clientY };
      if (!raf) raf = requestAnimationFrame(apply);
    });
    document.documentElement.addEventListener("pointerleave", () => {
      last = null;
      glow.classList.remove("on");
      rootStyle.setProperty("--px", "0");
      rootStyle.setProperty("--py", "0");
      resetTilt(pages[index].querySelector(".card"));
    });
  }

  /* ---------------------------------------------------------------
   * 4a. Pages 3-5 layout: reserve the same text-row height on every
   *     media page (the tallest message), so the frame row - and the
   *     frames - are identical on all three pages and no text is cut.
   * ------------------------------------------------------------- */
  function fitMediaText() {
    let tallest = 0;
    for (const box of $$(".media-text")) {
      const kids = [...box.children];
      const gap = parseFloat(getComputedStyle(box).rowGap) || 0;
      const h = kids.reduce((sum, k) => {
        const cs = getComputedStyle(k);
        return sum + k.offsetHeight + (parseFloat(cs.marginTop) || 0) + (parseFloat(cs.marginBottom) || 0);
      }, 0) + gap * Math.max(0, kids.length - 1);
      tallest = Math.max(tallest, h);
    }
    if (tallest) rootStyle.setProperty("--media-text-h", `${Math.ceil(tallest + 12)}px`); // + a little breathing room
  }
  // Re-measure whenever any text block changes size (window resize, zoom, rotation, font swap).
  // Safe from feedback loops: the blocks never shrink (flex-shrink: 0), so their size doesn't
  // depend on the row height we set here.
  if ("ResizeObserver" in window) {
    const last = new Map();
    const ro = new ResizeObserver((entries) => {
      let changed = false;
      for (const e of entries) {
        const key = `${Math.round(e.contentRect.width)}x${Math.round(e.contentRect.height)}`;
        if (last.get(e.target) !== key) { last.set(e.target, key); changed = true; }
      }
      if (changed) fitMediaText();
    });
    $$(".media-text, .media-text > *").forEach((el) => ro.observe(el));
  }

  /* ---------------------------------------------------------------
   * 4b. Page 5 videos: silent autoplay while the page is in view
   * ------------------------------------------------------------- */
  const VIDEO_MANIFEST = window.VIDEO_MANIFEST || {};
  const VIDEO_EXTS = ["mp4", "webm", "mov", "m4v", "MP4", "WEBM", "MOV"];
  const videos = $$("video[data-video]");
  const videoPage = videos.length ? videos[0].closest(".page") : null;
  const VIDEO_INDEX = pages.indexOf(videoPage);

  videos.forEach((v) => {
    const n = v.dataset.video;
    const holder = v.closest(".ph");
    holder.dataset.label = `video ${n}`;
    const list = MANIFEST_OK
      ? [VIDEO_MANIFEST[n]].filter(Boolean)
      : [...new Set([VIDEO_MANIFEST[n], ...VIDEO_EXTS.map((e) => `photos/video${n}.${e}`)].filter(Boolean))];
    let i = 0;
    v.muted = true;
    v.defaultMuted = true;
    v.setAttribute("muted", "");
    const tryNext = () => {
      if (i >= list.length) { holder.classList.add("missing"); console.warn(`[videos] video${n} not found in photos/ - showing a sunflower placeholder (add photos/video${n}.mp4 and restart serve.py)`); v.removeAttribute("src"); return; }
      v.src = list[i++];
      v.load();
    };
    v.addEventListener("error", tryNext);
    v.addEventListener("loadeddata", syncMedia);
    // The autoplay attribute would start playback on any page - only allow it on page 5.
    v.addEventListener("play", () => { if (index !== VIDEO_INDEX) v.pause(); });
    tryNext();
  });

  function playVideo(v) {
    v.muted = v.dataset.userUnmuted === "1" ? v.muted : true; // stay silent unless the viewer unmuted it
    const p = v.play();
    if (p && typeof p.catch === "function") p.catch(() => { /* autoplay refused or interrupted - controls still work */ });
  }
  videos.forEach((v) => v.addEventListener("volumechange", () => { if (!v.muted) v.dataset.userUnmuted = "1"; }));

  /** Play page-5 videos (silently) only while page 5 is the active page; pause them otherwise.
   *  Each page fills the whole viewport, so "page 5 is active" is the authoritative in-view signal. */
  let retryTimer = 0;
  function syncMedia() {
    const onVideoPage = index === VIDEO_INDEX && !document.hidden;
    for (const v of videos) {
      if (onVideoPage && !v.closest(".ph").classList.contains("missing")) {
        if (v.paused) playVideo(v);
      } else if (!v.paused) {
        v.pause();
      }
    }
    // A play() started mid-slide can be interrupted; re-check once the 3D slide-in has finished.
    clearTimeout(retryTimer);
    if (onVideoPage) retryTimer = setTimeout(() => videos.forEach((v) => {
      if (index === VIDEO_INDEX && v.paused && !v.closest(".ph").classList.contains("missing")) playVideo(v);
    }), DURATION + 150);
  }

  // IntersectionObserver as an extra trigger: as soon as a video frame becomes visible, sync playback.
  if ("IntersectionObserver" in window && videos.length) {
    const io = new IntersectionObserver((entries) => {
      if (entries.some((e) => e.isIntersecting)) syncMedia();
    }, { threshold: [0, 0.5] });
    videos.forEach((v) => io.observe(v));
  }
  document.addEventListener("visibilitychange", () => {
    if (document.hidden) videos.forEach((v) => v.pause());
    else syncMedia();
  });

  /* ---------------------------------------------------------------
   * 4c. Gentle falling leaves on pages 3, 4 and 5
   *     (each media card has its own .leaves layer; they only animate
   *      while that page is active - see .page.active .leaf in CSS)
   * ------------------------------------------------------------- */
  const LEAF_COLORS = ["#E8B83A", "#F2C94C", "#D9962B", "#E6A532", "#F5D36B", "#C9822A"];
  const LEAF_COUNT = innerWidth < 760 ? 9 : 14;
  const rand = (a, b) => a + Math.random() * (b - a);
  if (!reduceMotion) $$(".leaves").forEach((leavesBox) => {
    for (let i = 0; i < LEAF_COUNT; i++) {
      const COUNT = LEAF_COUNT;
      const leaf = document.createElement("span");
      leaf.className = "leaf";
      const dur = rand(14, 24);
      leaf.style.cssText = [
        `--x:${((i + Math.random() * 0.8) / COUNT * 100).toFixed(1)}%`,
        `--s:${rand(14, 26).toFixed(0)}px`,
        `--o:${rand(0.35, 0.55).toFixed(2)}`,
        `--c:${LEAF_COLORS[i % LEAF_COLORS.length]}`,
        `--dur:${dur.toFixed(1)}s`,
        `--delay:${(-rand(0, dur)).toFixed(1)}s`,
        `--sway:${rand(2.6, 4.4).toFixed(1)}s`,
        `--drift:${rand(-60, 60).toFixed(0)}px`,
        `--r0:${rand(-40, 40).toFixed(0)}deg`,
        `--r1:${rand(180, 420).toFixed(0)}deg`,
      ].join(";");
      leaf.innerHTML = '<svg aria-hidden="true"><use href="#leaf"/></svg>';
      leavesBox.appendChild(leaf);
    }
  });

  /* ---------------------------------------------------------------
   * 5. Torn-paper edges
   * ------------------------------------------------------------- */
  $$("[data-torn]").forEach((el) => {
    const side = el.dataset.torn;
    const pts = [];
    const steps = 46;
    for (let i = 0; i <= steps; i++) {
      const x = (i / steps) * 100;
      const y = 30 + Math.random() * 45 + (i % 2 ? 12 : 0);
      pts.push(`${x.toFixed(2)}% ${side === "top" ? y.toFixed(1) : (100 - y).toFixed(1)}%`);
    }
    const poly = side === "top" ? [...pts, "100% 100%", "0% 100%"] : ["0% 0%", "100% 0%", ...pts.reverse()];
    el.style.clipPath = `polygon(${poly.join(",")})`;
  });

  $$("[data-torn-corner]").forEach((el) => {
    const right = el.dataset.tornCorner === "br";
    const steps = 34;
    const edge = [];
    for (let i = 0; i <= steps; i++) {
      const t = i / steps;
      const base = 100 - 100 * Math.pow(1 - t, 1.6) * 0.92;
      const y = clamp(base + (Math.random() - 0.5) * 7 + (i % 2 ? 3 : -2), 2, 99);
      edge.push([right ? 100 - t * 100 : t * 100, y]);
    }
    const pts = [[right ? 100 : 0, 100], ...edge, [edge[edge.length - 1][0], 100]];
    el.style.clipPath = `polygon(${pts.map(([x, y]) => `${x.toFixed(2)}% ${y.toFixed(2)}%`).join(",")})`;
  });

  /* ---------------------------------------------------------------
   * 6. Confetti
   * ------------------------------------------------------------- */
  const layer = $("#confetti");
  const COLORS = ["#F7C531", "#FFE38A", "#E5AE2B", "#FFF3C9", "#8F701E", "#F6D365"];
  function confetti(x = innerWidth / 2, y = innerHeight / 2) {
    if (reduceMotion || !layer.animate) return;
    for (let i = 0; i < 70; i++) {
      const p = document.createElement("i");
      const size = 6 + Math.random() * 8;
      p.style.cssText = `left:${x}px;top:${y}px;width:${size}px;height:${size * 0.6}px;background:${COLORS[i % COLORS.length]}`;
      layer.appendChild(p);
      const ang = Math.random() * Math.PI * 2;
      const dist = 120 + Math.random() * 280;
      const dx = Math.cos(ang) * dist, dy = Math.sin(ang) * dist - 120;
      p.animate([
        { transform: "translate3d(0,0,0) rotate3d(1,1,0,0deg)", opacity: 1 },
        { transform: `translate3d(${dx}px, ${dy + 380}px, 0) rotate3d(1,1,0,${360 + Math.random() * 720}deg)`, opacity: 0 },
      ], { duration: 1400 + Math.random() * 900, easing: "cubic-bezier(.15,.6,.4,1)" }).onfinish = () => p.remove();
    }
  }

  let celebrated = false;
  new MutationObserver(() => {
    if (!celebrated && pages[pages.length - 1].classList.contains("active")) {
      celebrated = true;
      setTimeout(() => confetti(innerWidth / 2, innerHeight * 0.25), 700);
    }
  }).observe(pages[pages.length - 1], { attributes: true, attributeFilter: ["class"] });

  /* ---------------------------------------------------------------
   * Init - deep links beyond the gate land on the gate until YES.
   * ------------------------------------------------------------- */
  setVH();
  fitMediaText();
  if (document.fonts && document.fonts.ready) document.fonts.ready.then(fitMediaText); // re-measure once web fonts swap in
  const fromHash = parseInt(location.hash.slice(1), 10);
  if (fromHash >= 1 && fromHash <= pages.length) index = Math.min(fromHash - 1, GATE_INDEX);
  stage.classList.add("no-anim");
  render();
  void stage.offsetHeight;
  requestAnimationFrame(() => stage.classList.remove("no-anim"));

  // Small debug/test hook (read-only state)
  window.__bday = { get index() { return index; }, get gateOpen() { return gateOpen; } };
})();
